onClick:
{{
    (() => {
        const service = selLogSource.selectedOptionValue;
        const status = apiServiceStatus.data?.[service]?.status;
        const action = status === "stopped" ? "start" : "restart";

        return apiServiceStopStart.run({
            service: service,
            action: action,
            debug: false
        }).then(() => {
            showAlert(
                (action === "start" ? "Starting " : "Restarting ") + service + " in NORMAL mode...",
                "info"
            );
            apiServiceStatus.run();
        });
    })()
}}
